// MSB-first (Adafruit GFX) -> LSB-first (XBM, чего ждёт u8g2.drawXBM()) для одного байта
static uint8_t reverseBits(uint8_t b) {
  b = (b & 0xF0) >> 4 | (b & 0x0F) << 4;
  b = (b & 0xCC) >> 2 | (b & 0x33) << 2;
  b = (b & 0xAA) >> 1 | (b & 0x55) << 1;
  return b;
}

static bool needsFullClear = true;

// Форсирует полную перерисовку на следующем кадре — см. mute_animation.h
void resetMuteAnimation() {
  needsFullClear = true;
}

// Не блокирует и не зацикливается сама — просто рисует ТЕКУЩИЙ кадр и переключает его на
// следующий, если пришло время (см. MUTE_ANIM_FRAME_DELAY_MS). Пока эту функцию продолжают
// звать из loop() (main.cpp, пока isMuted) — анимация крутится непрерывно, пока Mute включён;
// как только перестанут звать — просто останавливается на последнем показанном кадре.
// Первый кадр после включения Mute (resetMuteAnimation()) — полная перерисовка (стирает то,
// что было на экране до Mute); все следующие — только тайлы под самой иконкой, а не весь
// буфер (1024 байта) — раньше каждый кадр слался полностью, и чем дольше сидишь в Mute, тем
// больше накапливается таких передач, тем выше шанс, что ОДНА из них по времени совпадёт
// с приёмом ИК-сигнала кнопки выхода из Mute (наводка от SPI на приёмник) и собьёт декодирование
void animateMuteFrame() {
  static uint8_t currentFrame = 0;
  static unsigned long lastFrameChange = 0;
  if (millis() - lastFrameChange < MUTE_ANIM_FRAME_DELAY_MS && !needsFullClear) {
    return; // Ещё не время следующего кадра — не шлём по SPI то же самое повторно
  }
  lastFrameChange = millis();
  currentFrame = (currentFrame + 1) % FRAME_COUNT;

  uint8_t buf[FRAME_BYTES];
  for (uint16_t i = 0; i < FRAME_BYTES; i++) {
    buf[i] = reverseBits(pgm_read_byte(&frames[currentFrame][i]));
  }

  if (needsFullClear) {
    needsFullClear = false;
    u8g2.clearBuffer();
    u8g2.drawXBM(MUTE_ANIM_X, MUTE_ANIM_Y, FRAME_WIDTH, FRAME_HEIGHT, buf);
    u8g2.sendBuffer();
    return;
  }

  // drawXBM не чистит фон сам (прозрачен для нулевых бит) — без явной очистки региона
  // предыдущий кадр мог бы местами "проглядывать" через новый
  u8g2.setDrawColor(0);
  u8g2.drawBox(MUTE_ANIM_X, MUTE_ANIM_Y, FRAME_WIDTH, FRAME_HEIGHT);
  u8g2.setDrawColor(1);
  u8g2.drawXBM(MUTE_ANIM_X, MUTE_ANIM_Y, FRAME_WIDTH, FRAME_HEIGHT, buf);

  // Переводим пиксельные координаты иконки в тайлы (1 тайл = 8x8px) и шлём по SPI
  // ТОЛЬКО их, а не весь буфер (u8g2.sendBuffer() послал бы все 1024 байта)
  uint8_t tx = MUTE_ANIM_X / 8;
  uint8_t tw = (MUTE_ANIM_X + FRAME_WIDTH - 1) / 8 - tx + 1;
  uint8_t ty = MUTE_ANIM_Y / 8;
  uint8_t th = (MUTE_ANIM_Y + FRAME_HEIGHT - 1) / 8 - ty + 1;
  u8g2.updateDisplayArea(tx, ty, tw, th);
}
